function object(x,y,r){
  push();
  noStroke();
  translate(x+50*sin(y*seed),y+50*cos(x*seed));
  noFill();


  var clridx = (x/grid + y/grid*(width/grid) +seed) % COLORS.length;

  let pulse = pow(max(0, sin(frameCount * 0.15+ x+y)), 2);
  let alpha = 80 + pulse * 120;

  var clr = color(COLORS[clridx]);
  clr.setAlpha(alpha);
  stroke(clr);

  for(var i = 0; i < 5; i++){
    rotate(PI/5+frameCount*0.01+ (x+y)*0.01 ); 
    ellipse(0,0,r,r*4);
  }

  var clr = color(COLORS[(clridx + 1) % COLORS.length]);
  clr.setAlpha(alpha);
  stroke(clr);
  for(var i = 0; i < 6; i++){
    rotate(TAU/6);
    for(var j = 0; j < (x/grid+y/grid+2); j++){ 
      circle(2*r*sin(frameCount*0.05),0,r*(1+0.2*j)*sin(frameCount*0.05+(x+y)*0.02));
    }
  }


  var clr = color(COLORS[(clridx + 2) % COLORS.length]);
  clr.setAlpha(alpha);
  fill(clr);
  for(var i = 0; i < 5; i++){
    rotate(-TAU/5- frameCount*0.02);
    rect(2*r*sin(frameCount*0.05),0,r/2);
  }
  pop()
}

